database-object.create:
BEGIN
    EXECUTE IMMEDIATE 'CREATE SEQUENCE LOADUNIT_SEQUENCE START WITH 1 INCREMENT BY 1';
EXCEPTION
    WHEN OTHERS THEN
        IF SQLCODE != -955 THEN
            RAISE;
        END IF;
END;

BEGIN
    EXECUTE IMMEDIATE 'CREATE SEQUENCE TOTE_SEQUENCE START WITH 1 INCREMENT BY 1';
EXCEPTION
    WHEN OTHERS THEN
        IF SQLCODE != -955 THEN
            RAISE;
        END IF;
END;

CREATE OR REPLACE TRIGGER TRG_STORAGE_CAPACITY
FOR INSERT OR UPDATE OF LOCATION_ID ON LOAD_UNIT
COMPOUND TRIGGER
    TYPE t_ids IS TABLE OF LOAD_UNIT.LOCATION_ID%TYPE;
    v_ids t_ids := t_ids();
    v_count NUMBER;

    AFTER EACH ROW IS
    BEGIN
        v_ids.EXTEND;
        v_ids(v_ids.COUNT) := :NEW.LOCATION_ID;
    END AFTER EACH ROW;

    AFTER STATEMENT IS
    BEGIN
        FOR i IN 1 .. v_ids.COUNT LOOP
            SELECT COUNT(*) INTO v_count
            FROM LOAD_UNIT u
            JOIN LOCATION l ON l.ID = u.LOCATION_ID
            WHERE l.ID = v_ids(i) AND l.DTYPE = 'STORAGE';

            IF v_count > 1 THEN
                RAISE_APPLICATION_ERROR(-20001, 'Storage location already contains a load unit');
            END IF;
        END LOOP;
    END AFTER STATEMENT;
END;
